using System;using System.Drawing;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
partial class AvalonInterno {
 readonly CheckBox meditationMirror=new CheckBox();MeditationController meditation;IMeditationRuntime meditationRuntime=new NativeMeditationRuntime();bool meditationPrimarySitting;
 bool MeditationPause {get{return shortcutActive&&meditationMirror.Checked&&meditationPrimarySitting;}}
 bool MeditationEngaged(int pid){return meditation!=null&&meditation.Holds(pid);}
 void InitMeditation(){meditationMirror.SetBounds(270,247,145,24);meditationMirror.Text="Espelhar meditação";meditationMirror.Font=new Font("Segoe UI",(float)(8)*global::UiScale.F);meditationMirror.ForeColor=Color.Cyan;meditationMirror.Checked=true;meditationMirror.CheckedChanged+=(o,e)=>{if(!syncing)Save();};Controls.Add(meditationMirror);hints.SetToolTip(meditationMirror,"Quando o principal medita ou levanta, os secundários selecionados acompanham. Funciona minimizado. Seguir aguarda o fim da meditação.");meditation=new MeditationController(meditationRuntime,blocked,s=>{if(!IsDisposed)BeginInvoke(new Action(()=>Note(s)));});}
 async Task MeditationTick(){if(meditation==null||closeInProgress||busy||buffing||teleport.Working||missions.Working)return;var primary=main.SelectedItem as Entry;var selected=followers.CheckedItems.Cast<Entry>().Where(rz=>!RotaLock.Busy(rz.Pid)).Where(e=>primary!=null&&e.Pid!=primary.Pid).Select(e=>e.Ref()).ToArray();try{meditationPrimarySitting=primary!=null&&meditationRuntime.Sitting(primary.Ref());}catch{return;}bool enabled=shortcutActive&&meditationMirror.Checked;busy=true;try{if(enabled&&meditationPrimarySitting&&selected.Any(e=>AttackEngaged(e.Pid)))await StopAttacks();await Task.Run(()=>meditation.Tick(primary==null?null:primary.Ref(),selected,enabled));}catch(Exception e){Note("Meditação: "+e.Message);}finally{busy=false;}}
}
